-- 004_schema_snapshot_fn.sql — public.team_tasks_schema_snapshot(): the schema snapshot, readable
-- over the API (Soren's paste design, 2026-11-05 16:00–16:07; Tasks AC's fix trip 3).
--
-- WHY. No agent holds the database password: Justin applies the migration by pasting it into the
-- Supabase SQL editor. So after Paste 2, the only way to compare live with the local golden snapshot
-- is through PostgREST with the secret key — which needs a function.
--
-- ONE SOURCE OF TRUTH. The query between the SNAPSHOT-QUERY markers below is the ONLY copy of the
-- snapshot query. schema-snapshot.mjs extracts it from this file and runs it directly (for a local
-- cluster, before or after migrating), so the function and the script return the same text BY
-- CONSTRUCTION; the acceptance suite also asserts it. Edit the query here, and nowhere else.
--
-- SECURITY. Read-only (STABLE, catalog reads only), SECURITY INVOKER, pinned search_path. EXECUTE to
-- service_role only; explicitly revoked from PUBLIC, anon and authenticated.
-- Idempotent (CREATE OR REPLACE). Applied with 001–003 in one transaction.
-- Truncation check: the last line of this file should read `FULL FILE LOADED` — if you don't see it, your load was truncated; re-read until you do.

create or replace function public.team_tasks_schema_snapshot()
returns text
language sql
stable
security invoker
set search_path = ''
as $snapshot$
-- SNAPSHOT-QUERY-BEGIN
select concat_ws(E'\n',
  '# server_version=' || current_setting('server_version'),
  '# server_version_num=' || current_setting('server_version_num'),

  (select string_agg(format('table %s: owner=%s', c.relname, pg_get_userbyid(c.relowner)), E'\n' order by c.relname)
     from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('rls %s: enabled=%s forced=%s', c.relname, c.relrowsecurity::text, c.relforcerowsecurity::text), E'\n' order by c.relname)
     from pg_class c
    where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(s.line, E'\n' order by s.relname, s.attnum) from (
     select c.relname, a.attnum,
            format('column %s #%s %s %s%s%s%s',
              c.relname,
              lpad(row_number() over (partition by c.relname order by a.attnum)::text, 2, '0'),
              a.attname,
              format_type(a.atttypid, a.atttypmod),
              case when a.attnotnull then ' NOT NULL' else '' end,
              case a.attidentity when 'a' then ' IDENTITY ALWAYS' when 'd' then ' IDENTITY BY DEFAULT' else '' end,
              case when a.attgenerated = 's' then ' GENERATED ' || pg_get_expr(d.adbin, d.adrelid)
                   when d.adbin is not null then ' DEFAULT ' || pg_get_expr(d.adbin, d.adrelid)
                   else '' end) as line
       from pg_class c
       join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
       left join pg_attrdef d on d.adrelid = c.oid and d.adnum = a.attnum
      where c.relnamespace = 'public'::regnamespace and c.relname in ('tasks','task_history','proposals')) s),

  (select string_agg(format('constraint %s.%s: %s', c.relname, con.conname, pg_get_constraintdef(con.oid)), E'\n' order by c.relname, con.conname)
     from pg_constraint con join pg_class c on c.oid = con.conrelid
    where c.relnamespace = 'public'::regnamespace and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('index %s.%s: %s', i.tablename, i.indexname, i.indexdef), E'\n' order by i.tablename, i.indexname)
     from pg_indexes i
    where i.schemaname = 'public' and i.tablename in ('tasks','task_history','proposals')),

  (select string_agg(format('trigger %s.%s: %s [enabled=%s]', c.relname, t.tgname, pg_get_triggerdef(t.oid), t.tgenabled), E'\n' order by c.relname, t.tgname)
     from pg_trigger t join pg_class c on c.oid = t.tgrelid
    where not t.tgisinternal and c.relnamespace = 'public'::regnamespace and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('policy %s.%s: %s %s to %s using (%s) with check (%s)',
            p.tablename, p.policyname, p.permissive, p.cmd, array_to_string(p.roles, ','), coalesce(p.qual, '-'), coalesce(p.with_check, '-')),
          E'\n' order by p.tablename, p.policyname)
     from pg_policies p
    where p.schemaname = 'public' and p.tablename in ('tasks','task_history','proposals')),

  (select string_agg(format('grant %s: %s %s%s', c.relname, coalesce(r.rolname, 'PUBLIC'), a.privilege_type,
                            case when a.is_grantable then ' WITH GRANT OPTION' else '' end),
          E'\n' order by c.relname, coalesce(r.rolname, 'PUBLIC'), a.privilege_type)
     from pg_class c
     cross join lateral aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
     left join pg_roles r on r.oid = a.grantee
    where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('sequence %s.%s: owner=%s', c.relname, att.attname, pg_get_userbyid(sc.relowner)), E'\n' order by c.relname, att.attname)
     from pg_class c
     join pg_attribute att on att.attrelid = c.oid and att.attidentity <> '' and not att.attisdropped
     join pg_class sc on sc.oid = pg_get_serial_sequence(format('public.%I', c.relname), att.attname)::regclass
    where c.relnamespace = 'public'::regnamespace and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('sequence-grant %s.%s: %s %s', c.relname, att.attname, coalesce(r.rolname, 'PUBLIC'), a.privilege_type),
          E'\n' order by c.relname, att.attname, coalesce(r.rolname, 'PUBLIC'), a.privilege_type)
     from pg_class c
     join pg_attribute att on att.attrelid = c.oid and att.attidentity <> '' and not att.attisdropped
     join pg_class sc on sc.oid = pg_get_serial_sequence(format('public.%I', c.relname), att.attname)::regclass
     cross join lateral aclexplode(coalesce(sc.relacl, acldefault('s', sc.relowner))) a
     left join pg_roles r on r.oid = a.grantee
    where c.relnamespace = 'public'::regnamespace and c.relname in ('tasks','task_history','proposals')),

  (select string_agg(format('function %s(%s): owner=%s security=%s volatility=%s config=%s body_md5=%s',
            p.proname, pg_get_function_identity_arguments(p.oid), pg_get_userbyid(p.proowner),
            case when p.prosecdef then 'DEFINER' else 'INVOKER' end, p.provolatile,
            coalesce(array_to_string(p.proconfig, ';'), '-'),
            md5(replace(p.prosrc, chr(13), ''))), E'\n' order by p.proname)
     from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'task\_%' or p.proname like 'tasks\_%' or p.proname = 'team_tasks_schema_snapshot')),

  (select string_agg(format('function-grant %s(%s): %s %s', p.proname, pg_get_function_identity_arguments(p.oid), coalesce(r.rolname, 'PUBLIC'), a.privilege_type),
          E'\n' order by p.proname, coalesce(r.rolname, 'PUBLIC'), a.privilege_type)
     from pg_proc p
     cross join lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     left join pg_roles r on r.oid = a.grantee
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'task\_%' or p.proname like 'tasks\_%' or p.proname = 'team_tasks_schema_snapshot')),

  -- Default privileges for FUTURE objects (QC Finding 1): LISTED by the compare, never a stop.
  (select string_agg(s.line, E'\n' order by s.line) from (
     select format('default-acl %s %s %s: %s %s',
              pg_get_userbyid(d.defaclrole), coalesce(n.nspname, '(all-schemas)'),
              case d.defaclobjtype when 'r' then 'tables' when 'S' then 'sequences' when 'f' then 'functions'
                                   when 'T' then 'types' when 'n' then 'schemas' else d.defaclobjtype::text end,
              coalesce(r.rolname, 'PUBLIC'), a.privilege_type) as line
       from pg_default_acl d
       left join pg_namespace n on n.oid = d.defaclnamespace
       cross join lateral aclexplode(d.defaclacl) a
       left join pg_roles r on r.oid = a.grantee) s)
)
-- SNAPSHOT-QUERY-END
$snapshot$
$s101$;
  execute $s102$
comment on function public.team_tasks_schema_snapshot() is
  'Read-only text description of tasks, task_history, proposals, the task functions, their grants and the default '
  'privileges — the same text schema-snapshot.mjs prints (it runs this very query, extracted from migration 004). '
  'For comparing live with the local golden snapshot over the API after the paste. EXECUTE: service_role only.'
$s102$;
  execute $s103$
revoke all on function public.team_tasks_schema_snapshot() from public, anon, authenticated, service_role
$s103$;
  execute $s104$
grant execute on function public.team_tasks_schema_snapshot() to service_role
$s104$;

  -- =========================================================================================
  -- (c) AFTER-ASSERTIONS. Every new column, CHECK, index, trigger (ENABLE ALWAYS), RLS setting,
  --     policy, and grant or revoke on the new objects — plus: nothing existing changed.
  -- =========================================================================================

  -- New columns, with their types
  select string_agg(e.col || ' ' || e.typ, ', ') into v_found
    from (values ('short_id','bigint'), ('owner','text'), ('created_by','text'), ('closed_at','timestamp with time zone'),
                 ('closing_note','text'), ('needed_by','date'), ('parent_id','uuid'), ('tags','text[]'),
                 ('addressed_to','text'), ('signed_at','timestamp with time zone'), ('signed_ref','text'),
                 ('linear_id','text'), ('linear_status','text'), ('search','tsvector')) as e(col, typ)
   where not exists (select 1 from pg_attribute a
                      where a.attrelid = 'public.tasks'::regclass and a.attname = e.col and not a.attisdropped
                        and format_type(a.atttypid, a.atttypmod) = e.typ);
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: tasks columns missing or mistyped: %. Everything was rolled back.', v_found;
  end if;
  if (select attidentity from pg_attribute where attrelid = 'public.tasks'::regclass and attname = 'short_id') <> 'a'
     or (select attgenerated from pg_attribute where attrelid = 'public.tasks'::regclass and attname = 'owner') <> 's'
     or (select attgenerated from pg_attribute where attrelid = 'public.tasks'::regclass and attname = 'search') <> 's' then
    raise exception 'AFTER-ASSERTION FAILED: short_id must be IDENTITY ALWAYS and owner/search GENERATED. Everything was rolled back.';
  end if;

  -- The original eight columns are untouched
  execute v_original_cols_sql into v_found;
  if v_found is distinct from v_original_cols_before then
    raise exception 'AFTER-ASSERTION FAILED: an existing tasks column changed. Before: % / After: %. Everything was rolled back.', v_original_cols_before, v_found;
  end if;

  -- The seven CHECKs
  select string_agg(nm, ', ') into v_found
    from unnest(array['tasks_status_allowed','tasks_title_max_80','tasks_closed_needs_note','tasks_signed_needs_ref',
                      'tasks_justin_needs_date','tasks_one_owner','tasks_addressed_to_shape']) as nm
   where not exists (select 1 from pg_constraint where conrelid = 'public.tasks'::regclass and conname = nm and contype = 'c');
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: CHECK constraint(s) missing: %. Everything was rolled back.', v_found;
  end if;

  -- Indexes (uniqueness lives in two of them)
  select string_agg(nm, ', ') into v_found
    from unnest(array['tasks_short_id_key','tasks_linear_id_key','tasks_owner_status_idx','tasks_addressed_to_status_idx',
                      'tasks_closed_at_idx','tasks_parent_id_idx','tasks_search_idx','task_history_task_id_id_idx']) as nm
   where to_regclass('public.' || nm) is null;
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: index(es) missing: %. Everything was rolled back.', v_found;
  end if;
  if not (select indisunique from pg_index where indexrelid = 'public.tasks_short_id_key'::regclass)
     or not (select indisunique from pg_index where indexrelid = 'public.tasks_linear_id_key'::regclass) then
    raise exception 'AFTER-ASSERTION FAILED: tasks_short_id_key and tasks_linear_id_key must be UNIQUE. Everything was rolled back.';
  end if;

  -- Triggers: all five present, on the right table, ENABLE ALWAYS
  select string_agg(e.tbl || '.' || e.tg, ', ') into v_found
    from (values ('tasks','tasks_before_write'), ('tasks','tasks_after_write'), ('tasks','tasks_refuse_delete'),
                 ('task_history','task_history_guard_insert'), ('task_history','task_history_refuse_change')) as e(tbl, tg)
   where not exists (select 1 from pg_trigger t
                      where t.tgrelid = ('public.' || e.tbl)::regclass and t.tgname = e.tg and t.tgenabled = 'A');
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: trigger(s) missing or not ENABLE ALWAYS: %. Everything was rolled back.', v_found;
  end if;

  -- RLS and the policy
  if not (select relrowsecurity from pg_class where oid = 'public.tasks'::regclass)
     or not (select relrowsecurity from pg_class where oid = 'public.task_history'::regclass) then
    raise exception 'AFTER-ASSERTION FAILED: row-level security must be enabled on tasks and task_history. Everything was rolled back.';
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'task_history'
                  and policyname = 'service_role_only' and cmd = 'ALL' and roles = array['service_role']::name[]) then
    raise exception 'AFTER-ASSERTION FAILED: task_history lacks the service_role_only policy. Everything was rolled back.';
  end if;

  -- task_history grants: service_role exactly SELECT + INSERT; anon/authenticated (and so PUBLIC) nothing
  if not has_table_privilege('service_role', 'public.task_history', 'SELECT')
     or not has_table_privilege('service_role', 'public.task_history', 'INSERT')
     or has_table_privilege('service_role', 'public.task_history', 'UPDATE')
     or has_table_privilege('service_role', 'public.task_history', 'DELETE')
     or has_table_privilege('service_role', 'public.task_history', 'TRUNCATE') then
    raise exception 'AFTER-ASSERTION FAILED: service_role must hold exactly SELECT and INSERT on task_history. Everything was rolled back.';
  end if;
  if has_table_privilege('anon', 'public.task_history', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
     or has_table_privilege('authenticated', 'public.task_history', 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE') then
    raise exception 'AFTER-ASSERTION FAILED: anon or authenticated (or PUBLIC) holds a privilege on task_history. Everything was rolled back.';
  end if;

  -- The two new identity sequences: no client role holds anything
  select string_agg(r.rol || ' on ' || s.seq, ', ') into v_found
    from (values (pg_get_serial_sequence('public.tasks', 'short_id')), (pg_get_serial_sequence('public.task_history', 'id'))) as s(seq)
    cross join (values ('anon'), ('authenticated'), ('service_role')) as r(rol)
   where has_sequence_privilege(r.rol, s.seq, 'USAGE,SELECT,UPDATE');
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: a client role holds a privilege on a new sequence: %. Everything was rolled back.', v_found;
  end if;

  -- Functions: all present, SECURITY INVOKER, search_path pinned; trigger functions executable by no client role;
  -- the helpers and the snapshot function by service_role only
  select string_agg(nm, ', ') into v_found
    from unnest(array['task_roster','task_request_actor','tasks_before_write','tasks_after_write','tasks_refuse_delete',
                      'task_history_guard_insert','task_history_refuse_change','team_tasks_schema_snapshot']) as nm
   where not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = nm
                       and not p.prosecdef and p.proconfig @> array['search_path=""']);
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: function(s) missing, SECURITY DEFINER, or without a pinned search_path: %. Everything was rolled back.', v_found;
  end if;
  select string_agg(r.rol || ' -> ' || f.fn, ', ') into v_found
    from (values ('tasks_before_write'), ('tasks_after_write'), ('tasks_refuse_delete'),
                 ('task_history_guard_insert'), ('task_history_refuse_change')) as f(fn)
    cross join (values ('anon'), ('authenticated'), ('service_role')) as r(rol)
   where has_function_privilege(r.rol, ('public.' || f.fn || '()')::regprocedure, 'EXECUTE');
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: a client role can execute a trigger function: %. Everything was rolled back.', v_found;
  end if;
  select string_agg(f.fn, ', ') into v_found
    from (values ('task_roster'), ('task_request_actor'), ('team_tasks_schema_snapshot')) as f(fn)
   where not has_function_privilege('service_role', ('public.' || f.fn || '()')::regprocedure, 'EXECUTE')
      or has_function_privilege('anon', ('public.' || f.fn || '()')::regprocedure, 'EXECUTE')
      or has_function_privilege('authenticated', ('public.' || f.fn || '()')::regprocedure, 'EXECUTE');
  if v_found is not null then
    raise exception 'AFTER-ASSERTION FAILED: EXECUTE must be service_role only on: %. Everything was rolled back.', v_found;
  end if;
  if (select provolatile from pg_proc where oid = 'public.team_tasks_schema_snapshot()'::regprocedure) <> 's' then
    raise exception 'AFTER-ASSERTION FAILED: team_tasks_schema_snapshot must be STABLE (read-only). Everything was rolled back.';
  end if;

  -- Nothing existing changed: tasks' grants, and public.proposals
  execute v_tasks_grants_sql into v_found;
  if v_found is distinct from v_tasks_grants_before then
    raise exception 'AFTER-ASSERTION FAILED: grants on public.tasks changed. Before: % / After: %. Everything was rolled back.', v_tasks_grants_before, v_found;
  end if;
  execute v_proposals_sql into v_found;
  if v_found is distinct from v_proposals_before then
    raise exception 'AFTER-ASSERTION FAILED: public.proposals changed. Before: % / After: %. Everything was rolled back.', v_proposals_before, v_found;
  end if;

  -- (d) the final statement
  raise exception 'DRY RUN OK — nothing was changed (% rows; % NOT VALID)', (select count(*) from public.tasks), (select count(*) from pg_constraint where conrelid = 'public.tasks'::regclass and contype = 'c' and not convalidated);
end
